import os


class Config:
    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # Directories and File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_2"
    SUBMISSION_DIR = "./submission"

    # Input CSVs (generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Sample submission for formatting reference
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "best_model.pt")

    # Cache Files (using .npz for efficient storage of processed tensors)
    CACHE_TRAIN_DATA = os.path.join(WORKING_DIR, "train_data.npz")
    CACHE_VAL_DATA = os.path.join(WORKING_DIR, "val_data.npz")
    CACHE_TEST_DATA = os.path.join(WORKING_DIR, "test_data.npz")

    # -------------------------------------------------------------------------
    # Data Processing Parameters
    # -------------------------------------------------------------------------
    # Mapping for atomic species found in the dataset
    ATOM_MAP = {"Al": 0, "Ga": 1, "In": 2, "O": 3}
    NUM_ATOM_TYPES = len(ATOM_MAP)

    # Debugging: Set to an integer (e.g., 100) to limit dataset size, or None for full data
    DEBUG_DATA_LIMIT = None

    # -------------------------------------------------------------------------
    # Model Hyperparameters (LCDS)
    # -------------------------------------------------------------------------
    # Atomic Branch
    ATOM_INPUT_DIM = NUM_ATOM_TYPES  # 4
    ATOM_HIDDEN_DIM = 256  # Wide expansion (Cite Lesson 6)

    # Lattice Branch
    LATTICE_INPUT_DIM = 6  # a, b, c, alpha, beta, gamma
    LATTICE_HIDDEN_DIM = 128  # Increased capacity (Cite Lesson 9)

    # Fusion & Regressor
    # Atomic (256*2 for dual pooling) + Lattice (128) = 640
    FUSION_HIDDEN_DIMS = [256, 128, 64]
    DROPOUT = 0.1
    ACTIVATION = "leaky_relu"  # Options: relu, leaky_relu, gelu

    # -------------------------------------------------------------------------
    # Training Settings
    # -------------------------------------------------------------------------
    BATCH_SIZE = 32
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 150  # Maximum number of epochs
    EARLY_STOPPING_PATIENCE = 20  # Stop if validation metric doesn't improve

    # Scheduler settings (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.5
    SCHEDULER_PATIENCE = 10
    SCHEDULER_MIN_LR = 1e-6

    @classmethod
    def setup(cls):
        """Creates necessary working directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories on module import
Config.setup()
